void BuildUI(){tabs.Dock=DockStyle.Fill;tabs.Visible=false;Panel home=new Panel{Name="工作台"},browser=new Panel{Name="内置浏览器 / 登录"},settings=new Panel{Name="版本与更新"};home.Padding=Padding.Empty;browser.Padding=Padding.Empty;settings.Padding=Padding.Empty;tabs.AddPages(home,browser,settings);app.Dock=DockStyle.Fill;home.Controls.Add(app);web.Dock=DockStyle.Fill;browser.Controls.Add(web);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=85,Padding=new Padding(8),WrapContents=true};address.Width=600;address.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){Navigate(address.Text);e.SuppressKeyPress=true;}};bar.Controls.Add(Btn("后退",delegate{if(web.CanGoBack)web.GoBack();}));bar.Controls.Add(Btn("前进",delegate{if(web.CanGoForward)web.GoForward();}));bar.Controls.Add(Btn("刷新",delegate{web.Reload();}));bar.Controls.Add(address);bar.Controls.Add(Btn("打开",delegate{Navigate(address.Text);}));tasks.Width=350;tasks.DropDownStyle=ComboBoxStyle.DropDownList;bar.Controls.Add(tasks);bar.Controls.Add(Btn("刷新任务",async delegate{await LoadTasks();}));bar.Controls.Add(Btn("摘录当前网页",async delegate{await CapturePage();}));browser.Controls.Add(bar);var bottom=new Panel{Dock=DockStyle.Bottom,Height=45};status.Dock=DockStyle.Fill;status.Padding=new Padding(10,4,0,0);navProgress.Dock=DockStyle.Bottom;navProgress.Height=4;bottom.Controls.Add(status);bottom.Controls.Add(navProgress);browser.Controls.Add(bottom);var pane=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(35),FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};pane.Controls.Add(new Label{Text="轻摘 v1.0.0",Font=new Font(Font.FontFamily,22,FontStyle.Bold),AutoSize=true});pane.Controls.Add(new Label{Text="独立桌面版 · 本机数据与网站登录资料单独保存",AutoSize=true,Margin=new Padding(0,15,0,15)});pane.Controls.Add(Btn("检查更新",delegate{CheckForUpdates(true);}));pane.Controls.Add(Btn("打开数据目录",delegate{Process.Start("explorer.exe",dataRoot);}));pane.Controls.Add(Btn("导入旧版资料目录",delegate{ImportOldData();}));pane.Controls.Add(new Label{Text="更新流程：下载 → SHA-256 / 大小校验 → 安全解包 → 关闭主程序 → 替换文件 → 选择是否重启。\n\n需要登录的网站：在内置浏览器亲自登录，再回到工作台运行任务。\n浏览器登录资料仅在本机保存；退出网站账号可在网页内完成。\n更新时保留 UserData，不替换任务、报告、下载文件与登录资料。",AutoSize=true,MaximumSize=new Size(900,0),Margin=new Padding(0,20,0,0)});settings.Controls.Add(pane);Controls.Add(tabs);tabs.BringToFront();splash.BringToFront();}
Button Btn(string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=31,Padding=new Padding(5),Margin=new Padding(4)};b.Click+=delegate{try{action();}catch(Exception e){MessageBox.Show(e.Message,"轻摘");}};return b;}
static int FreePort(){var l=new TcpListener(IPAddress.Loopback,0);l.Start();int p=((IPEndPoint)l.LocalEndpoint).Port;l.Stop();return p;}
static bool SafeUrl(string url){Uri u;return Uri.TryCreate(url,UriKind.Absolute,out u)&&(u.Scheme=="https"||u.Scheme=="http")&&string.IsNullOrEmpty(u.UserInfo);}
void Navigate(string value){string url=value.Trim();if(!url.Contains("://"))url=url.Contains(".")?"https://"+url:"https://www.bing.com/search?q="+Uri.EscapeDataString(url);if(!SafeUrl(url)){status.Text="请输入HTTP/HTTPS网址或搜索关键词";return;}web.Source=new Uri(url);}
async Task Popup(CoreWebView2NewWindowRequestedEventArgs e,CoreWebView2Environment env){var def=e.GetDeferral();try{var f=new Form{Text="网页窗口",Size=new Size(1100,800),StartPosition=FormStartPosition.CenterParent};var v=new WebView2{Dock=DockStyle.Fill};f.Controls.Add(v);popups.Add(f);f.FormClosed+=delegate{popups.Remove(f);v.Dispose();};f.Show(this);await v.EnsureCoreWebView2Async(env);v.CoreWebView2.Settings.AreHostObjectsAllowed=false;v.CoreWebView2.Settings.IsWebMessageEnabled=false;v.CoreWebView2.NavigationStarting+=(s,n)=>{if(!SafeUrl(n.Uri)&&n.Uri!="about:blank")n.Cancel=true;};e.NewWindow=v.CoreWebView2;e.Handled=true;}catch(Exception ex){status.Text=ex.Message;e.Handled=true;}finally{def.Complete();}}
async Task<Dictionary<string,object>> Get(string path){var text=await client.GetStringAsync(baseUrl+path);return json.Deserialize<Dictionary<string,object>>(text);}
async Task<Dictionary<string,object>> Post(string path,object body){using(var result=await client.PostAsync(baseUrl+path,new StringContent(json.Serialize(body),Encoding.UTF8,"application/json"))){string text=await result.Content.ReadAsStringAsync();var value=json.Deserialize<Dictionary<string,object>>(text);if(!result.IsSuccessStatusCode)throw new Exception(value.ContainsKey("error")?Convert.ToString(value["error"]):"操作失败");return value;}}
class TaskItem{public string Id,Name;public override string ToString(){return Name;}}
async Task LoadTasks(){try{var state=await Get("/api/state");tasks.Items.Clear();foreach(var obj in (IEnumerable)state["tasks"]){var t=(Dictionary<string,object>)obj;string type=t.ContainsKey("collectType")?Convert.ToString(t["collectType"]):"article";if(type=="images"||type=="video")continue;tasks.Items.Add(new TaskItem{Id=Convert.ToString(t["id"]),Name=Convert.ToString(t["name"])});}if(tasks.Items.Count>0)tasks.SelectedIndex=0;}catch(Exception e){status.Text=e.Message;}}
async Task CapturePage(){try{var t=tasks.SelectedItem as TaskItem;if(t==null)throw new Exception("请先在工作台创建文字摘录任务，再刷新任务列表");if(pollBusy)throw new Exception("任务正在读取浏览器，请稍后再摘录");string url=web.Source.ToString();if(!SafeUrl(url))throw new Exception("当前网页地址不可摘录");status.Text="正在摘录登录后的当前网页…";string html=await Html();var result=await Post("/api/desktop/import",new{taskId=t.Id,url=url,html=html});status.Text="已保存："+Convert.ToString(result["title"]);MessageBox.Show("已保存到摘录档案。","轻摘");}catch(Exception e){status.Text=e.Message;MessageBox.Show(e.Message,"摘录未完成");}}
async Task<string> Html(){string raw=await web.ExecuteScriptAsync("(()=>{for(const i of document.images){if(i.currentSrc)i.setAttribute('data-collected-current-src',i.currentSrc);if(i.naturalWidth)i.setAttribute('data-natural-width',i.naturalWidth);if(i.naturalHeight)i.setAttribute('data-natural-height',i.naturalHeight);}return document.documentElement.outerHTML;})()");string html=json.Deserialize<string>(raw);if(html.Length>2*1024*1024)throw new Exception("页面超过2MB，请缩小摘录范围");return html;}
async Task PollCommands(){if(pollBusy||closing||client==null)return;pollBusy=true;string id=null;try{var response=await Get("/api/desktop/commands");if(response["command"]==null)return;var c=(Dictionary<string,object>)response["command"];id=Convert.ToString(c["id"]);string kind=Convert.ToString(c["kind"]),url=Convert.ToString(c["url"]);if(!SafeUrl(url))throw new Exception("不支持此地址");status.Text="任务正在使用登录浏览器，请暂勿切换网页…";if(kind=="image"){var payload=await Image(url,c.ContainsKey("referer")?Convert.ToString(c["referer"]):"");await Post("/api/desktop/result",new{id=id,base64=payload.Base64,contentType=payload.ContentType});}else{if(kind=="open"){tabs.SelectedIndex=1;Navigate(url);await Post("/api/desktop/result",new{id=id,url=url});return;}if(web.Source==null||web.Source.ToString()!=url)await Go(url);await Task.Delay(1000);int rounds=c.ContainsKey("scrollRounds")?Convert.ToInt32(c["scrollRounds"]):0;for(int i=0;i<Math.Min(3,rounds);i++){await web.ExecuteScriptAsync("window.scrollBy(0,innerHeight)");await Task.Delay(700);}string html=await Html();await Post("/api/desktop/result",new{id=id,url=web.Source.ToString(),html=html});}status.Text="本批网页读取完成";}catch(Exception e){status.Text="浏览器读取失败："+e.Message;if(id!=null){Post("/api/desktop/result",new{id=id,error=e.Message}).ContinueWith(t=>{});}}finally{pollBusy=false;}}
class ImagePayload{public string Base64,ContentType;}
async Task<ImagePayload> Image(string url,string referer){var cookies=await web.CoreWebView2.CookieManager.GetCookiesAsync(url);var list=new List<object>();foreach(var c in cookies)list.Add(new{name=c.Name,value=c.Value,domain=c.Domain,path=c.Path,secure=c.IsSecure});string helper=Path.Combine(root,"app","desktop-image.cjs");using(var proc=new Process{StartInfo=new ProcessStartInfo(Path.Combine(root,"runtime","node.exe"),"\""+helper+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true}}){proc.Start();var stdout=proc.StandardOutput.ReadToEndAsync();var stderr=proc.StandardError.ReadToEndAsync();await proc.StandardInput.WriteAsync(json.Serialize(new{url=url,referer=SafeUrl(referer)?referer:"",userAgent=web.CoreWebView2.Settings.UserAgent,cookies=list}));proc.StandardInput.Close();await Task.Run(()=>proc.WaitForExit());string output=await stdout,error=await stderr;if(proc.ExitCode!=0)throw new Exception(error);var result=json.Deserialize<Dictionary<string,object>>(output);return new ImagePayload{Base64=Convert.ToString(result["base64"]),ContentType=Convert.ToString(result["contentType"])};}}
async Task Go(string url){var completion=new TaskCompletionSource<bool>();EventHandler<CoreWebView2NavigationCompletedEventArgs> handler=null;handler=(s,e)=>completion.TrySetResult(e.IsSuccess);web.NavigationCompleted+=handler;try{web.Source=new Uri(url);var winner=await Task.WhenAny(completion.Task,Task.Delay(45000));if(winner!=completion.Task)throw new Exception("网页加载超时，请在内置浏览器登录后重试");if(!await completion.Task)throw new Exception("网页加载失败");}finally{web.NavigationCompleted-=handler;}}
void ImportOldData(){using(var dialog=new FolderBrowserDialog{Description="选择旧版包含data.json的目录"}){if(dialog.ShowDialog()!=DialogResult.OK)return;if(!File.Exists(Path.Combine(dialog.SelectedPath,"data.json"))){MessageBox.Show("该目录没有data.json");return;}if(MessageBox.Show("导入会覆盖本软件现有任务资料。建议先备份UserData。是否继续？","导入资料",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;File.WriteAllText(Path.Combine(dataRoot,"import-next-start.txt"),dialog.SelectedPath,Encoding.UTF8);MessageBox.Show("已登记导入目录。请关闭软件后运行“导入旧资料.cmd”完成导入，再启动软件。","轻摘");}}
bool checkingUpdate;
async void CheckForUpdates(bool manual){if(checkingUpdate)return;checkingUpdate=true;try{var currentInfo=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"version.json")));Version current=ReleaseFeed.ParseVersion(Convert.ToString(currentInfo["version"]));var release=await ReleaseClient.Latest(current);if(release==null||release.Version<=current){if(manual)MessageBox.Show("当前已是最新版本：v"+current,"检查更新");return;}string note=release.Notes??"";if(!AskUpdate(current,release.Version,note))return;LaunchUpdater();}catch(Exception e){if(manual)MessageBox.Show("检查更新失败："+e.Message,"轻摘");}finally{checkingUpdate=false;}}
bool AskUpdate(Version current,Version next,string notes){using(var d=new Form{Text="发现新版本",Width=640,Height=480,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false}){var title=new Label{Text="当前版本：v"+current+"     新版本：v"+next,Dock=DockStyle.Top,Height=45,Padding=new Padding(16,12,0,0)};var content=new TextBox{Text=notes,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill};var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=55,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(8)};var later=new Button{Text="稍后",DialogResult=DialogResult.Cancel,AutoSize=true};var now=new Button{Text="立即更新",DialogResult=DialogResult.OK,AutoSize=true};buttons.Controls.Add(now);buttons.Controls.Add(later);d.AcceptButton=now;d.CancelButton=later;d.Controls.Add(content);d.Controls.Add(title);d.Controls.Add(buttons);return d.ShowDialog(this)==DialogResult.OK;}}
void LaunchUpdater(){string updater=Path.Combine(root,"Updater.exe");if(!File.Exists(updater))throw new Exception("更新程序不存在");string temp=Path.Combine(Path.GetTempPath(),"GentlyPickUpdater-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(updater,temp);var p=Process.GetCurrentProcess();string args="--root \""+root.TrimEnd('\\')+"\" --pid "+p.Id+" --start "+p.StartTime.ToUniversalTime().Ticks;Process.Start(new ProcessStartInfo(temp,args){UseShellExecute=true});}
void OnClose(object sender,FormClosingEventArgs e){if(closing)return;closing=true;poll.Stop();foreach(var f in popups.ToArray())f.Close();try{app.Dispose();web.Dispose();}catch{}try{if(backend!=null&&!backend.HasExited){backend.Kill();backend.WaitForExit(5000);}}catch{}try{if(adapter!=null&&!adapter.HasExited)adapter.Kill();}catch{}jobs.Dispose();if(client!=null)client.Dispose();}
}
class PageHost:Panel {
readonly List<Control> pages=new List<Control>();int selected;
public int SelectedIndex {get{return selected;}set{if(value<0||value>=pages.Count)throw new ArgumentOutOfRangeException("value");SuspendLayout();selected=value;for(int i=0;i<pages.Count;i++)pages[i].Visible=i==selected;pages[selected].BringToFront();ResumeLayout(true);}}
public void AddPages(params Control[] items){foreach(var page in items){page.Dock=DockStyle.Fill;page.Margin=Padding.Empty;pages.Add(page);Controls.Add(page);}SelectedIndex=0;}
}
class JobGuard:IDisposable{IntPtr handle;[System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern IntPtr CreateJobObject(IntPtr attributes,string name);[System.Runtime.InteropServices.DllImport("kernel32.dll")]static extern bool SetInformationJobObject(IntPtr job,int infoClass,IntPtr info,uint size);[System.Runtime.InteropServices.DllImport("kernel32.dll")]static extern bool AssignProcessToJobObject(IntPtr job,IntPtr process);[System.Runtime.InteropServices.DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);public JobGuard(){handle=CreateJobObject(IntPtr.Zero,null);if(handle==IntPtr.Zero)throw new Exception("无法创建进程管理器");IntPtr info=System.Runtime.InteropServices.Marshal.AllocHGlobal(144);try{for(int i=0;i<144;i++)System.Runtime.InteropServices.Marshal.WriteByte(info,i,0);System.Runtime.InteropServices.Marshal.WriteInt32(info,16,0x2000);if(!SetInformationJobObject(handle,9,info,144))throw new Exception("无法设置子进程退出策略");}finally{System.Runtime.InteropServices.Marshal.FreeHGlobal(info);}}public void Add(Process p){if(!AssignProcessToJobObject(handle,p.Handle))throw new Exception("无法管理数据服务子进程");}public void Dispose(){if(handle!=IntPtr.Zero){CloseHandle(handle);handle=IntPtr.Zero;}}}

}

